const ExcelJS = require('exceljs');
async function main() {
  const workbook = new ExcelJS.Workbook();
  await workbook.xlsx.readFile('skills/OfficeBench/testbed/data/travel_expenses.xlsx');
  const sheet = workbook.getWorksheet('Travel Expenses');
  sheet.eachRow((row, rowNum) => {
    console.log('Row ' + rowNum + ':', row.values.slice(1).join(' | '));
  });
}
main().catch(console.error);
